one=np.ones_like(t)
def dic(k):
  G=np.tanh(k*t)
  D={}
  tb={'1':one,'t':t,'t2':t*t,'G':G,'tG':t*G,'G2':G*G,'1/t':1/t}
  for i in range(4):
    for n,v in tb.items():
      D[f'P{i}*{n}']=P**i*v
  return D
